--
function UIChooseCookingPopupDialog:InitData()
    self._allBattleFoodData = {}

    local t = self:GetAllBattleFoodData()
    local _t = {}
    for k, v in pairs(t) do
        --if CookingUtils.IsUnlockFood(v.id) then
            table.insert(_t, v)
        --end
        if table.count(_t) == PageFoodCount then
            table.insert(self._allBattleFoodData, _t)
            _t = {}
        elseif k == table.count(t) then 
            table.insert(self._allBattleFoodData, _t)
            _t = {}
        end
    end
end

--绘制
function UIChooseCookingPopupDialog:RefreshFoodView()
    self._curPageFoodData = self:GetCurPageFoodData()

    for k, v in pairs(self._curPageFoodData) do
        local go = self.Content.transform:Find("go"..k)
        if not go then
            go = CfUtils.InstantiateGo(self.Cell, self.Content)
            go.name = "go"..k
        end
        KTool.SetActive(go, true)

        local scr = CfUtils.GetLuaScr(go, UIChooseCookingFoodNode) 
        if scr then
            local data = self._curPageFoodData[k]
            scr:Refresh(data, k, function(lastUseId)
                lastUseId = checkNumber(lastUseId)
                if lastUseId <= 0 then
                    return
                end

                for k, v in pairs(self._curPageFoodData) do
                    if checkNumber(v.id) == lastUseId then
                        local lastGo = self.Content.transform:Find("go"..k)
                        if lastGo then
                            local lastScr = CfUtils.GetLuaScr(lastGo, UIChooseCookingFoodNode) 
                            if lastScr then
                                lastScr:FillSelf()
                            end
                        end
                        return
                    end
                end
            end, self._curQuestId)
        end
    end

    if table.count(self._curPageFoodData) < PageFoodCount then
        for i = table.count(self._curPageFoodData) + 1, PageFoodCount do
            local go = self.Content.transform:Find("go"..i)
            if go then
                KTool.SetActive(go, false)
            end
        end
    end

    CfUtils.FillText(self.TextNumber, self._curPageInd.."<color=#a6a6a6>/"..table.count(self._allBattleFoodData).."</color>")
end

--当前页面的数据
function UIChooseCookingPopupDialog:GetCurPageFoodData()
    local ind = checkNumber(self._curPageInd)
    if ind <= 0 then
        return {}
    end
    local t = self._allBattleFoodData
    if ind > table.count(t) then
        return {}
    end

    return t[ind]
end

--所有的套餐食品
function UIChooseCookingPopupDialog:GetAllBattleFoodData()
    local t = CfUtils.GetCfTable(AutoIds.IdSetting2017)
    if not t then
        return {}
    end
    local _t = {}
    local useVo 
    for k, v in pairs(t) do
        local vo = CookingFoodVo.New()
        vo:FillVo(v)
        --if CookingUtils.IsUnlockFood(vo.id) then
            local isCurUse, num = CookingUtils.IsUseBattleFood(vo.id)
            if isCurUse then
                useVo = vo
            else
                table.insert(_t, vo)
            end
        --end
    end 

    for i = 1, #_t - 1 do
        for j = i + 1, #_t do
            local vo1 = _t[i]
            local vo2 = _t[j]
            local isChange = false
            if CookingUtils.IsUnlockFood(vo2.id) and not CookingUtils.IsUnlockFood(vo1.id) then
                isChange = true
            elseif CookingUtils.IsUnlockFood(vo2.id) and CookingUtils.IsUnlockFood(vo1.id) then
                if CookingUtils.IsCollectFood(vo2.id) and not CookingUtils.IsCollectFood(vo1.id) then
                    isChange = true
                else
                    isChange = checkNumber(vo2.id) < checkNumber(vo1.id)
                end
            else
                isChange = checkNumber(vo2.id) < checkNumber(vo1.id)
            end
            if isChange then
                local buffer = _t[i]
                _t[i] = _t[j]
                _t[j] = buffer
            end
        end
    end

    --[[
    table.sort(_t, function(a, b)
        local aNum = GoodsUtils.GetThingNo(a.id)
        local bNum = GoodsUtils.GetThingNo(b.id)

        if CookingUtils.IsCollectFood(b.id) and CookingUtils.IsCollectFood(a.id) then
            if aNum == bNum then
                return checkNumber(a.id) < checkNumber(b.id)
            else
                return aNum > bNum    
            end
        elseif not CookingUtils.IsCollectFood(b.id) and not CookingUtils.IsCollectFood(a.id) then
            if aNum == bNum then
                return checkNumber(a.id) < checkNumber(b.id)
            else
                return aNum > bNum    
            end
        elseif not CookingUtils.IsCollectFood(b.id) and CookingUtils.IsCollectFood(a.id) then
            return true
        end

        return false
    end)
    ]]

    if useVo then
        table.insert(_t, 1, useVo)
    end
    return _t
end

--左
function UIChooseCookingPopupDialog:OnBtnLeft()  
    if self._curPageInd <= 1 then
        return
    end
    self._curPageInd = self._curPageInd - 1
    self:RefreshFoodView()
    self:RefreshArrow()
    self:RefreshPagePoints()
end

--右
function UIChooseCookingPopupDialog:OnBtnRight()
    local maxNum = table.count(self._allBattleFoodData)
    if self._curPageInd >= maxNum then
        return
    end
    self._curPageInd = self._curPageInd + 1
    self:RefreshFoodView()
    self:RefreshArrow()
    self:RefreshPagePoints()
end

function UIChooseCookingPopupDialog:RefreshArrow()
    local lStatus, rStatus = 1, 1
    if self._curPageInd <= 1 then
        lStatus = 2
    end
    local maxNum = table.count(self._allBattleFoodData)
    if self._curPageInd >= maxNum then
        rStatus = 2
    end
    CfUtils.SetUISwitchImage(self.BtnArrowLeft.transform:Find("ImgArrow"), lStatus)
    CfUtils.SetUISwitchImage(self.BtnArrowRight.transform:Find("ImgArrow"), rStatus)

    local lRedPoint = false
    local rRedPoint = false
    local t
    if self._curPageInd > 1 then
        t = self._allBattleFoodData[self._curPageInd - 1]
        lRedPoint = self:IsMapHasNew(t)
    end

    if self._curPageInd < maxNum then
        t = self._allBattleFoodData[self._curPageInd + 1]
        rRedPoint = self:IsMapHasNew(t)
    end
    KTool.SetActive(self.BtnArrowLeft.transform:Find("CommonRedPoint"), lRedPoint)
    KTool.SetActive(self.BtnArrowRight.transform:Find("CommonRedPoint"), rRedPoint)
end

function UIChooseCookingPopupDialog:RefreshPagePoints()
    local count = table.count(self._allBattleFoodData)
    if count <= 1 then
        KTool.SetActive(self.PageGroup, false)
        return
    end

    for i = 1, count do
        local go = self.PageGroup.transform:Find("point"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.ImgSquare, self.PageGroup)
            go.name = "point"..i
            KTool.SetActive(go, true)
        end
        local status = (checkNumber(self._curPageInd) == i) and 1 or 2
        CfUtils.SetUISwitchImage(go, status)
    end
end

--是否有新的数据
function UIChooseCookingPopupDialog:IsMapHasNew(t)
    if not t then
        return false
    end
    for k, v in pairs(t) do
        if CookingUtils.IsNewRecipe(v.menu) then
            return true
        end
    end
    return false
end

function UIChooseCookingPopupDialog:OnBattleFoodCollectChange()
    self:RefreshFoodView()
end

function UIChooseCookingPopupDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.EventBattleFoodCollectChange = Events.AddListener(Constants.EventNames.BattleFoodCollectChange, Bind(self, self.OnBattleFoodCollectChange))
    end))
    return coWait
end

function UIChooseCookingPopupDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.RemoveListener(Constants.EventNames.BattleFoodCollectChange, self.EventBattleFoodCollectChange)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIChooseCookingPopupDialog
